/* RechnungFlow UI: no third-party runtime, no inline script, no stored authentication tokens. */
const app=document.querySelector('#app');
const languages=['en','de','fa'];
let language=languages.includes(localStorage.getItem('rf.language'))?localStorage.getItem('rf.language'):'en';
let dict={},user=null,csrf='',config={},policy={},pageEpoch=0,currentInvoice=null,currentSuppliers=[],currentUsers=[],currentJobs=[],dialog=null;
let filters={q:'',stage:'',page:0};let activeInvoiceTab='overview';
const icons={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 invoice:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v2"/>',building:'<path d="M4 21V7l8-4 8 4v14M2 21h20M8 9v2M12 9v2M16 9v2M8 14v2M12 14v2M16 14v2M10 21v-3h4v3"/>',
 export:'<path d="M14 3h7v7M21 3l-9 9M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="16" cy="17" r="3" fill="currentColor" stroke="none"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M15 6.5h3M15 17.5h3"/>',
 book:'<path d="M12 5C8 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-2-1-6-2-10 1zm0 0v16"/>',upload:'<path d="M12 16V3M7 8l5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13M7 11l5 5 5-5M4 15v6h16v-6"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',logout:'<path d="M9 4H4v16h5M12 12h9m-4-4 4 4-4 4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',plus:'<path d="M12 5v14M5 12h14"/>',warning:'<path d="m12 3 10 18H2zM12 9v5m0 3v.1"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',refresh:'<path d="M20 10a8 8 0 1 0-1 7M20 3v7h-7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.invoice}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>dict[k]??k;
const errorText=code=>dict['err.'+code]||dict['issue.'+code]||`${t('common.error')} (${code})`;
const has=(...roles)=>!!user&&roles.some(r=>user.roles.includes(r));
const num=v=>new Intl.NumberFormat(language==='fa'?'fa-IR':language==='de'?'de-DE':'en-GB').format(v??0);
const money=(v,c='EUR')=>{try{return new Intl.NumberFormat(language==='fa'?'fa-IR':language==='de'?'de-DE':'en-GB',{style:'currency',currency:c||'EUR',maximumFractionDigits:2}).format(Number(v??0));}catch{return `${v??0} ${c}`;}};
const date=v=>{if(!v)return '—';try{return new Intl.DateTimeFormat(language==='fa'?'fa-IR-u-ca-gregory':language==='de'?'de-DE':'en-GB',{year:'numeric',month:'short',day:'2-digit',timeZone:'UTC'}).format(new Date(v));}catch{return v;}};
const initials=name=>String(name||'RF').split(/[\s-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const languageButtons=()=>`<div class="languages" aria-label="${esc(t('common.language'))}">${languages.map(l=>`<button type="button" data-lang="${l}" class="${language===l?'active':''}" aria-pressed="${language===l}">${l==='fa'?'فا':l.toUpperCase()}</button>`).join('')}</div>`;
const color=status=>['PASS','KOSIT_PASS','APPROVED','EXPORTED','DELIVERED','VERIFIED'].includes(status)?'green':['EXCEPTION','BASIC_FAIL','FAIL','FAILED','ERROR','REJECTED'].includes(status)?'red':['REVIEW','APPROVAL','IN_FLIGHT'].includes(status)?'blue':['UNKNOWN','DEMO_ONLY','UNAVAILABLE','BLOCKED','NOT_VALIDATED','TIMEOUT'].includes(status)?'amber':'gray';
const badge=status=>`<span class="pill dot ${color(status)}">${esc(dict['stage.'+status]||status)}</span>`;
const button=(action,label,kind='secondary',ic='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${esc(action)}" ${extra}>${ic?icon(ic):''}${esc(t(label))}</button>`;
const heading=(title,subtitle,action='')=>`<div class="page-heading"><div><h1>${esc(t(title))}</h1><p>${esc(t(subtitle))}</p></div>${action}</div>`;
const field=(label,name,value='',type='text',required=true,hint='')=>`<div class="form-field"><label for="f-${name}">${esc(t(label))}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'autocomplete="new-password" minlength="14" maxlength="128"':''}>${hint?`<span class="hint">${esc(t(hint))}</span>`:''}</div>`;
const textarea=(label,name,value='')=>`<div class="form-field"><label for="f-${name}">${esc(t(label))}</label><textarea id="f-${name}" name="${name}" maxlength="2000" required>${esc(value)}</textarea></div>`;
const empty=(detail='common.emptyDetail')=>`<div class="empty"><div class="empty-icon">${icon('invoice')}</div><h3>${esc(t('common.empty'))}</h3><p>${esc(t(detail))}</p></div>`;
function toast(message,isError=false){const el=document.createElement('div');el.className='toast'+(isError?' error':'');el.textContent=message;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
async function api(path,options={}){
 const headers=new Headers(options.headers||{});if(options.body!==undefined&&!(options.body instanceof File)&&!(options.body instanceof Blob)&&!(options.body instanceof ArrayBuffer)){headers.set('Content-Type','application/json');options.body=JSON.stringify(options.body);}
 if(csrf&&!['GET','HEAD'].includes(options.method||'GET'))headers.set('X-CSRF-Token',csrf);
 let response;try{response=await fetch(path,{credentials:'same-origin',...options,headers});}catch{const e=new Error(t('common.error'));e.code='NETWORK_ERROR';throw e;}
 let result;try{result=await response.json();}catch{throw new Error(t('common.error'));}
 if(!response.ok){const code=result.error?.code||'INTERNAL_ERROR';if(response.status===401&&user){user=null;csrf='';renderLogin();}const error=new Error(errorText(code));error.code=code;error.requestId=result.error?.requestId;throw error;}
 return result;
}
async function loadLanguage(l){language=l;localStorage.setItem('rf.language',l);dict=await (await fetch(`/locales/${l}.json`)).json();document.documentElement.lang=l;document.documentElement.dir=l==='fa'?'rtl':'ltr';}
function closeDialog(){if(dialog){dialog.close();dialog.remove();dialog=null;}}
function openDialog(title,content,onSubmit,label='common.save'){
 closeDialog();const d=document.createElement('dialog');d.innerHTML=`<form><header class="dialog-header"><h2>${esc(t(title))}</h2><button type="button" class="btn icon-only" data-close-dialog aria-label="${esc(t('common.close'))}">${icon('close')}</button></header><div class="dialog-body">${content}<p class="form-error" role="alert"></p></div><footer class="dialog-footer"><button type="button" class="btn secondary" data-close-dialog>${esc(t('common.cancel'))}</button><button type="submit" class="btn primary">${esc(t(label))}</button></footer></form>`;
 document.body.append(d);dialog=d;d.showModal();d.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>{d.close();d.remove();if(dialog===d)dialog=null;}));
 d.addEventListener('cancel',()=>{d.remove();if(dialog===d)dialog=null;});
 d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const submit=d.querySelector('[type=submit]'),err=d.querySelector('.form-error');submit.disabled=true;err.textContent='';
   try{const shouldClose=await onSubmit(new FormData(e.target),d);if(shouldClose!==false&&d.isConnected){d.close();d.remove();if(dialog===d)dialog=null;}}
   catch(ex){if(d.isConnected)err.textContent=ex.message;else toast(ex.message,true);}
   finally{if(d.isConnected)submit.disabled=false;}
 });return d;
}
function renderLogin(){pageEpoch++;currentInvoice=null;app.innerHTML=`<div class="login-shell"><section class="login-art"><div class="logo"><img src="/icon.svg" alt="">RechnungFlow</div><div class="login-message"><div class="eyebrow">${esc(t('login.eyebrow'))}</div><h1>${esc(t('login.hero'))}</h1><p>${esc(t('login.description'))}</p><div class="login-features"><span>${icon('shield')}${esc(t('login.feature1'))}</span><span>${icon('check')}${esc(t('login.feature2'))}</span><span>${icon('book')}${esc(t('login.feature3'))}</span></div></div><div class="login-footer">${esc(t('login.preview'))}</div></section><section class="login-panel"><div class="login-panel-top">${languageButtons()}</div><form id="login-form" class="login-form"><h2>${esc(t('login.title'))}</h2><p class="subtitle">${esc(t('login.subtitle'))}</p>${field('login.workspace','tenant',config.workspace||'demo')}${field('login.username','login','admin')}<div class="form-field"><label for="login-password">${esc(t('login.password'))}</label><input id="login-password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">${esc(t('login.submit'))}${icon('arrow')}</button><p class="login-hint">${esc(t('login.hint'))}</p></form><div class="login-panel-footer">RechnungFlow · 0.1.0</div></section></div>`;
 app.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type=submit]');submit.disabled=true;f.querySelector('.form-error').textContent='';
  try{const answer=await api('/api/auth/login',{method:'POST',body:data});user=answer.user;csrf=answer.csrf;if(answer.user.mustChangePassword){renderShell();changePassword(true);}else{policy=await api('/api/policy');renderShell();await renderPage();}}
  catch(ex){if(f.isConnected){f.querySelector('.form-error').textContent=ex.message;submit.disabled=false;}}
 });
}
const nav=[['dashboard','grid'],['invoices','invoice'],['approvals','check'],['suppliers','building'],['jobs','export'],['audit','clock'],['users','users'],['policy','settings'],['system','server'],['docs','book']];
function allowedNav(n){if(['jobs','audit'].includes(n))return has('ADMIN','FINANCE','AUDITOR');if(['users','system'].includes(n))return has('ADMIN');return true;}
function route(){return (location.hash.slice(1)||'dashboard').split('/');}
function renderShell(){if(!user)return renderLogin();const current=route()[0];app.innerHTML=`<aside class="sidebar"><div class="logo"><img src="/icon.svg" alt="">RechnungFlow</div><div class="workspace-chip"><span class="square">${icon('building')}</span><span>${esc(policy.name||user.tenant)}</span></div><div class="nav-label">${esc(t('nav.workspace'))}</div><nav class="nav-list">${nav.filter(([n])=>allowedNav(n)).map(([n,ic],i)=>`${n==='audit'?`<div class="nav-label">${esc(t('nav.governance'))}</div>`:''}<a class="nav-link ${current===n||(current==='invoice'&&n==='invoices')?'active':''}" href="#${n}" ${current===n?'aria-current="page"':''}>${icon(ic)}${esc(t('nav.'+n))}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="user-avatar">${esc(initials(user.name))}</div><div class="sidebar-person"><strong>${esc(user.name)}</strong><small>${esc(user.roles.map(r=>t('role.'+r)).slice(0,2).join(' · '))}</small></div><button class="btn icon-only" data-action="logout" title="${esc(t('login.logout'))}" aria-label="${esc(t('login.logout'))}">${icon('logout')}</button></div></aside><div class="main"><header class="topbar"><button class="btn icon-only mobile-menu" data-action="menu" aria-label="${esc(t('common.menu'))}">${icon('menu')}</button><div class="breadcrumb"><span>RechnungFlow</span><span>/</span><b id="breadcrumb-page"></b></div><div class="spacer"></div>${languageButtons()}<button class="avatar" data-action="password" title="${esc(t('login.changePassword'))}" aria-label="${esc(t('login.changePassword'))}">${esc(initials(user.name))}</button></header><main class="content" id="content"></main></div>`;}
function modeBanner(){return `<div class="mode-banner ${policy.mode==='DEMO'?'':'strict'}">${icon(policy.mode==='DEMO'?'warning':'shield')}<span>${esc(t(policy.mode==='DEMO'?'demo.banner':'strict.banner'))}</span></div>`;}
async function renderPage(){if(!user)return;const epoch=++pageEpoch;currentInvoice=null;const content=document.querySelector('#content');if(!content){renderShell();return renderPage();}const [view,id]=route();
 document.querySelectorAll('.nav-link').forEach(n=>{const active=n.getAttribute('href')==='#'+(view==='invoice'?'invoices':view);n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});
 document.querySelector('#breadcrumb-page').textContent=t('nav.'+(view==='invoice'?'invoices':view));document.querySelector('.sidebar')?.classList.remove('open');
 content.innerHTML=modeBanner()+`<div class="loading"><span class="spinner"></span><div>${esc(t('common.loading'))}</div></div>`;
 try{let html;switch(view){
  case'dashboard':html=dashboard(await api('/api/dashboard'));break;
  case'invoices':case'approvals':{let stage=filters.stage;if(view==='approvals')stage='APPROVAL';const q=new URLSearchParams({q:filters.q,stage,page:filters.page,pageSize:25});html=invoiceList(await api('/api/invoices?'+q),view==='approvals');break;}
  case'invoice':{const data=await api('/api/invoices/'+encodeURIComponent(id));if(epoch!==pageEpoch)return;currentInvoice=data;html=invoiceDetail(data);break;}
  case'suppliers':{const data=await api('/api/suppliers');if(epoch!==pageEpoch)return;currentSuppliers=data.items;html=suppliersPage(data.items);break;}
  case'jobs':{const data=await api('/api/jobs');if(epoch!==pageEpoch)return;currentJobs=data.items;html=jobsPage(data);break;}
  case'audit':html=auditPage(await api('/api/audit'));break;
  case'users':{const [u,k]=await Promise.all([api('/api/users'),api('/api/keys')]);if(epoch!==pageEpoch)return;currentUsers=u.items;html=usersPage(u.items,k.items);break;}
  case'policy':{const p=await api('/api/policy');if(epoch!==pageEpoch)return;policy=p;html=policyPage(p);break;}
  case'system':html=systemPage(await api('/api/system'));break;
  case'docs':html=await docsPage(id||'quickstart');break;
  default:location.hash='dashboard';return;
 }if(epoch!==pageEpoch)return;content.innerHTML=modeBanner()+html;bindPage(view);}
 catch(ex){if(epoch!==pageEpoch||!user)return;content.innerHTML=modeBanner()+`<div class="card pad"><div class="notice error">${esc(ex.message)}</div>${button('refresh','common.refresh','secondary','refresh')}</div>`;}
}
function invoiceTable(items,{compact=false}={}){if(!items.length)return empty();return `<div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('invoices.number'))}</th><th>${esc(t('invoices.supplier'))}</th><th class="right">${esc(t('invoices.amount'))}</th><th>${esc(t('common.status'))}</th>${compact?'':`<th>${esc(t('invoices.validation'))}</th><th>${esc(t('invoices.due'))}</th>`}<th><span class="sr-only">${esc(t('common.actions'))}</span></th></tr></thead><tbody>${items.map((i,n)=>`<tr><td><a class="title-link" href="#invoice/${esc(i.id)}"><bdi>${esc(i.number||'—')}</bdi></a><span class="subline">${esc(i.syntax||'XML')}${i.credit?' · '+esc(t('invoices.credit')):''}</span></td><td><div class="supplier-cell"><span class="supplier-initial tone${n%4}">${esc(initials(i.seller))}</span><span>${esc(i.seller||'—')}</span></div></td><td class="right"><strong>${esc(money(i.payable,i.currency))}</strong></td><td>${badge(i.stage)}</td>${compact?'':`<td>${badge(i.validation)}</td><td>${esc(date(i.dueDate))}</td>`}<td><a href="#invoice/${esc(i.id)}" class="btn icon-only" aria-label="${esc(t('common.open'))}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(d){policy=d.policy;const c=d.counts;return `<div class="page-heading"><div><div class="eyebrow">${esc(t('dashboard.eyebrow'))}</div><h1>${esc(t('dashboard.title'))}</h1><p>${esc(t('dashboard.subtitle'))}</p></div>${has('ADMIN','INTAKE')?button('upload','common.upload','primary','plus'):''}</div><div class="stats">${[['dashboard.total',d.total,'invoice',''],['dashboard.review',c.REVIEW,'search',''],['dashboard.approval',c.APPROVAL,'check',''],['dashboard.exceptions',c.EXCEPTION,'warning','amber']].map(([k,v,ic,cls])=>`<div class="card stat ${cls}"><div class="stat-top"><span>${esc(t(k))}</span><span class="stat-icon">${icon(ic)}</span></div><div class="value">${num(v)}</div><div class="caption">${esc(t('app.tagline'))}</div></div>`).join('')}</div><div class="overview-grid"><div class="stack"><div class="card pad"><div class="amount-band"><div><span class="caption">${esc(t('dashboard.openAmount'))}</span>${Object.entries(d.openAmounts).map(([currency,value])=>`<div class="amount">${esc(money(value,currency))}</div>`).join('')||'<div class="amount">—</div>'}</div><div class="vertical-line"></div><div><span class="caption">${esc(t('dashboard.overdue'))}</span><div class="amount">${num(d.overdue)}</div></div></div><h3>${esc(t('dashboard.lifecycle'))}</h3><div class="lifecycle">${[['REVIEW',c.REVIEW],['APPROVAL',c.APPROVAL],['APPROVED',c.APPROVED],['EXPORTED',c.EXPORTED]].map(([k,v])=>`<div class="lifecycle-step"><strong>${num(v)}</strong><span>${esc(t('stage.'+k))}</span></div>`).join('')}</div></div><div class="card"><div class="card-header"><h2>${esc(t('dashboard.recent'))}</h2><a class="btn ghost small" href="#invoices">${esc(t('dashboard.viewAll'))}${icon('arrow')}</a></div>${invoiceTable(d.recent,{compact:true})}</div></div><div class="stack"><div class="card"><div class="card-header"><h2>${esc(t('dashboard.priorities'))}</h2>${icon('clock')}</div><div class="priority-list">${[['review-filter','search','dashboard.review','dashboard.priorityReview',c.REVIEW],['exception-filter','warning','dashboard.exceptions','dashboard.priorityException',c.EXCEPTION],['jobs-route','export','nav.jobs','dashboard.priorityExport',d.jobsPending]].map(([action,ic,title,text,v])=>`<button class="priority" data-action="${action}"><span class="priority-icon">${icon(ic)}</span><span><h3>${esc(t(title))}</h3><p>${esc(t(text))}</p></span><span class="count">${num(v)}</span></button>`).join('')}</div></div><div class="card pad"><h2>${esc(t('dashboard.controls'))}</h2><div class="control-list"><div class="control-item">${icon('lock')}${esc(t('dashboard.originals'))}</div><div class="control-item">${icon('users')}${esc(t('dashboard.separation'))}</div><div class="control-item">${icon('shield')}${esc(t('system.validator'))}: ${esc(t(d.validator.configured?'system.configured':'system.missing'))}</div></div><p class="control-note">${esc(t('dashboard.explain'))}</p></div></div></div>`;}
function invoiceList(d,approvals){return heading(approvals?'invoices.approvalTitle':'invoices.title',approvals?'invoices.approvalSubtitle':'invoices.subtitle',has('ADMIN','INTAKE')?button('upload','common.upload','primary','plus'):'')+`<form class="filters" id="filters"><div class="search-field">${icon('search')}<label class="sr-only" for="invoice-search">${esc(t('common.search'))}</label><input id="invoice-search" name="q" value="${esc(filters.q)}" placeholder="${esc(t('common.search'))}"></div>${approvals?'':`<label class="sr-only" for="stage-filter">${esc(t('common.status'))}</label><select id="stage-filter" name="stage"><option value="">${esc(t('common.all'))}</option>${['EXCEPTION','REVIEW','APPROVAL','APPROVED','EXPORT_PENDING','EXPORTED','REJECTED','SUPERSEDED'].map(s=>`<option value="${s}" ${filters.stage===s?'selected':''}>${esc(t('stage.'+s))}</option>`).join('')}</select>`}<button class="btn secondary" type="submit">${esc(t('common.filter'))}</button>${button('refresh','common.refresh','secondary','refresh')}${has('ADMIN','FINANCE','AUDITOR')?`<a class="btn secondary" href="/api/invoices/export.csv">${icon('download')}CSV</a>`:''}</form><div class="card">${invoiceTable(d.items)}<div class="table-footer"><span>${num(d.total)} · ${esc(t('nav.invoices'))}</span><div class="row"><button class="btn secondary small" data-page="${d.page-1}" ${d.page===0?'disabled':''}>${esc(t('common.previous'))}</button><span>${num(d.page+1)} ${esc(t('common.of'))} ${num(Math.max(1,Math.ceil(d.total/d.pageSize)))}</span><button class="btn secondary small" data-page="${d.page+1}" ${(d.page+1)*d.pageSize>=d.total?'disabled':''}>${esc(t('common.next'))}</button></div></div></div>`;}
function invoiceDetail(i){const d=i.data||{},m=d.totals||{},s=d.seller||{},buyer=d.buyer||{},p=i.policy||{};return `<div class="row between wrap"><a class="btn ghost" href="#invoices">${esc(t('common.back'))}</a><div class="row wrap"><a class="btn secondary small" href="/api/invoices/${i.id}/original">${icon('download')}${esc(t('detail.original'))}</a>${has('ADMIN','FINANCE','AUDITOR','REVIEWER','APPROVER')?`<a class="btn secondary small" href="/api/invoices/${i.id}/evidence">${icon('shield')}${esc(t('detail.evidence'))}</a>`:''}</div></div><div class="detail-grid section-gap"><div><div class="card invoice-hero"><div>${badge(i.stage)}<h2><bdi>${esc(d.number||i.filename)}</bdi></h2><p class="muted">${esc(s.name||'—')}</p><span class="pill gray">${esc(d.syntax||'XML')}</span>${d.credit?' '+badge('REJECTED').replace(esc(t('stage.REJECTED')),esc(t('invoices.credit'))):''}</div><div class="amount-column"><small>${esc(t('invoices.amount'))}</small><div class="amount-big">${esc(money(m.payable,d.currency))}</div><small>${esc(t('invoices.due'))}: ${esc(date(d.dueDate))}</small></div></div><div class="tabs" role="tablist">${['overview','validation','history','comments'].map(tab=>`<button class="tab ${activeInvoiceTab===tab?'active':''}" data-tab="${tab}" role="tab" aria-selected="${activeInvoiceTab===tab}">${esc(t('detail.'+tab))}</button>`).join('')}</div>${activeInvoiceTab==='overview'?invoiceOverview(i):activeInvoiceTab==='validation'?invoiceValidation(i):activeInvoiceTab==='history'?historyView(i.history):commentsView(i)}</div><aside class="detail-sidebar">${workflowPanel(i)}<div class="card pad section-gap"><h3>${esc(t('detail.hash'))}</h3><p class="mono" dir="ltr">${esc(i.sha256)}</p><div class="metric"><span>${esc(t('detail.retainUntil'))}</span><span>${esc(date(i.retainUntil))}</span></div><div class="metric"><span>${esc(t('detail.hold'))}</span><b>${esc(t(i.legalHold?'common.yes':'common.no'))}</b></div>${has('ADMIN','FINANCE')?button('hold','detail.toggleHold','ghost small'):''}<p class="control-note">${esc(t('detail.holdHelp'))}</p></div></aside></div>`;}
function invoiceOverview(i){const d=i.data||{},m=d.totals||{};return `<div class="card pad"><div class="two-col">${[['seller','detail.seller'],['buyer','detail.buyer']].map(([key,label])=>{const p=d[key]||{};return `<div class="data-block"><div class="label">${esc(t(label))}</div><div class="name">${esc(p.name||'—')}</div><p>${esc(p.street||'')}</p><p>${esc([p.postalCode,p.city,p.country].filter(Boolean).join(' '))}</p><p class="mono" dir="ltr">${esc(p.taxId||p.registration||'')}</p></div>`;}).join('')}</div><div class="detail-meta">${[['detail.issueDate',date(d.issueDate)],['invoices.due',date(d.dueDate)],['detail.buyerReference',d.buyerReference],['detail.purchaseOrder',d.purchaseOrder],['detail.iban',d.iban],['detail.policyVersion',i.policy.policyVersion]].map(([k,v])=>`<div><div class="label">${esc(t(k))}</div><div class="value"><bdi>${esc(v||'—')}</bdi></div></div>`).join('')}</div></div><div class="card section-gap"><div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('detail.description'))}</th><th class="right">${esc(t('detail.quantity'))}</th><th class="right">${esc(t('detail.unitPrice'))}</th><th class="right">${esc(t('detail.vat'))}</th><th class="right">${esc(t('detail.net'))}</th></tr></thead><tbody>${(d.lines||[]).map(l=>`<tr><td>${esc(l.description)}<span class="subline">${esc(l.id)} · ${esc(l.unit)}</span></td><td class="right">${num(l.quantity)}</td><td class="right">${esc(money(l.unitPrice,d.currency))}</td><td class="right">${esc(l.vatRate)}% · ${esc(l.vatCategory)}</td><td class="right">${esc(money(l.net,d.currency))}</td></tr>`).join('')}</tbody></table></div><div class="card-header"><div class="spacer"></div><div class="totals">${[['detail.net','net'],['detail.vat','tax'],['detail.gross','gross'],['detail.prepaid','prepaid'],['detail.rounding','rounding'],['invoices.amount','payable']].map(([k,key])=>`<div class="total-line ${key==='payable'?'grand':''}"><span>${esc(t(k))}</span><span>${esc(money(m[key],d.currency))}</span></div>`).join('')}</div></div></div>${d.note?`<div class="card pad section-gap"><h3>${esc(t('common.note'))}</h3><p>${esc(d.note)}</p></div>`:''}${i.metadata?.costCenter?`<div class="card pad section-gap"><div class="two-col"><div><small>${esc(t('detail.costCenter'))}</small><p>${esc(i.metadata.costCenter)}</p></div><div><small>${esc(t('detail.glAccount'))}</small><p>${esc(i.metadata.glAccount)}</p></div></div><p>${esc(i.metadata.note)}</p></div>`:''}${i.supersedes?`<div class="notice section-gap">${esc(t('detail.supersedes'))}: <a href="#invoice/${esc(i.supersedes)}">${esc(i.supersedes)}</a></div>`:''}`;}
function invoiceValidation(i){const v=i.validation||{},o=v.official||{};return `<div class="card pad"><div class="row between"><h2>${esc(t('detail.basic'))}</h2>${badge(v.basic||'NOT_RUN')}</div>${(v.issues||[]).map(x=>`<div class="issue">${badge('FAIL')}<div class="issue-text"><p>${esc(dict['issue.'+x.code]||errorText(x.code))}</p><small class="mono">${esc(x.code)} · ${esc(x.field)}</small></div></div>`).join('')||`<p class="notice success section-gap">${esc(t('detail.noBlockers'))}</p>`}</div><div class="card pad section-gap"><div class="row between"><h2>${esc(t('detail.official'))}</h2>${badge(o.status||'NOT_RUN')}</div><div class="metric"><span>${esc(t('common.version'))}</span><span class="mono">${esc(o.version||'—')} / ${esc(o.configuration||'—')}</span></div><p class="notice warn section-gap">${esc(t('dashboard.explain'))}</p>${(o.issues||[]).map(x=>`<div class="issue"><div class="issue-text"><strong class="mono">${esc(x.rule)} / ${esc(x.severity)}</strong><p>${esc(x.message)}</p><small class="mono">${esc(x.location)}</small></div></div>`).join('')}${o.reportSha256?`<a class="btn secondary" href="/api/invoices/${i.id}/report">${icon('download')}${esc(t('detail.report'))}</a>`:''}<div class="section-gap"><h3>${esc(t('detail.validationHistory'))}</h3>${(i.validationHistory||[]).map((run,n)=>`<div class="metric"><span>${num(n+1)} · ${esc(date(run.checkedAt))} ${badge(run.official?.status||'NOT_RUN')}</span>${run.official?.reportSha256?`<a href="/api/invoices/${i.id}/report?attempt=${n}" class="btn secondary small">${esc(t('detail.report'))}</a>`:''}</div>`).join('')}</div>${has('ADMIN','REVIEWER')&&['EXCEPTION','REVIEW'].includes(i.stage)?button('revalidate','detail.revalidate','secondary','refresh'):''}</div><div class="card pad section-gap"><h2>${esc(t('detail.blockers'))}</h2>${(i.blockers||[]).map(code=>`<div class="blocker">${icon('warning')}<span>${esc(errorText(code))}</span></div>`).join('')||`<p class="notice success section-gap">${esc(t('detail.noBlockers'))}</p>`}</div>`;}
function historyView(events){return `<div class="card pad"><h2>${esc(t('detail.history'))}</h2><div class="timeline">${events?.length?events.map(e=>`<div class="event"><span class="event-dot"></span><div><h3>${esc(dict['audit.'+e.action]||e.action)}</h3><p>${esc(date(e.at))} · <bdi class="mono">${esc(e.actor)}</bdi></p>${e.detail?.reason?`<p>${esc(e.detail.reason)}</p>`:''}</div>`).join(''):`<p>${esc(t('detail.noHistory'))}</p>`}</div></div>`;}
function commentsView(i){return `<div class="card pad"><h2>${esc(t('detail.comments'))}</h2><div class="section-gap">${i.comments?.length?i.comments.map(c=>`<article class="comment"><div class="comment-head"><strong>${esc(c.name)}</strong><span>${esc(date(c.at))}</span></div><p>${esc(c.note)}</p></article>`).join(''):`<p class="muted">${esc(t('detail.noComments'))}</p>`}</div>${has('ADMIN','INTAKE','REVIEWER','APPROVER','FINANCE')?`<form id="comment-form">${textarea('common.note','note')}<button type="submit" class="btn primary">${esc(t('detail.addComment'))}</button><p class="form-error" role="alert"></p></form>`:''}</div>`;}
function workflowPanel(i){const advanced=['APPROVAL','APPROVED','EXPORT_PENDING','EXPORTED'].includes(i.stage);let actions='';
 if(i.stage==='REVIEW'&&has('ADMIN','REVIEWER'))actions+=button('review','detail.completeReview','primary full','check');
 if(i.stage==='APPROVAL'&&has('ADMIN','APPROVER'))actions+=button('approve','detail.approve','primary full','check');
 if(i.stage==='APPROVED'&&has('ADMIN','FINANCE'))actions+=button('export','detail.export','primary full','export');
 if(['EXCEPTION','REVIEW'].includes(i.stage)&&has('ADMIN','REVIEWER'))actions+=button('revalidate','detail.revalidate','secondary full','refresh');
 if(['EXCEPTION','REJECTED','REVIEW'].includes(i.stage)&&has('ADMIN','INTAKE'))actions+=button('correction','upload.correct','secondary full','upload');
 if(!i.supplier&&has('ADMIN','REVIEWER'))actions+=button('supplier-from-invoice','detail.registerSupplier','secondary full','building');
 if(['EXCEPTION','REVIEW','APPROVAL','APPROVED'].includes(i.stage)&&has('ADMIN','REVIEWER','APPROVER'))actions+=button('reject','detail.reject','danger full');
 return `<div class="card pad"><div class="row between"><h2>${esc(t('detail.workflow'))}</h2>${icon('shield')}</div><div class="workflow-steps">${[['invoices.received',true,false,i.createdByName],['detail.completeReview',advanced,i.stage==='REVIEW',i.reviewedByName],['nav.approvals',['APPROVED','EXPORT_PENDING','EXPORTED'].includes(i.stage),i.stage==='APPROVAL',`${num(i.approvals?.length||0)} / ${num(i.requiredApprovals)}`],['nav.jobs',i.stage==='EXPORTED',i.stage==='EXPORT_PENDING','']].map(([k,complete,current,n],idx)=>`<div class="workflow-step ${complete?'complete':''} ${current?'current':''}"><span class="step-icon">${complete?icon('check'):idx+1}</span><div><strong>${esc(t(k))}</strong>${n?`<small>${esc(n)}</small>`:''}</div></div>`).join('')}</div>${(i.blockers||[]).map(code=>`<div class="blocker">${icon('warning')}<span>${esc(errorText(code))}</span></div>`).join('')}<div class="workflow-actions section-gap">${actions||`<p class="hint">${esc(t('detail.actionsUnavailable'))}</p>`}<p class="hint">${esc(t('detail.selfApproval'))}</p></div></div>`;}
function suppliersPage(items){return heading('suppliers.title','suppliers.subtitle',has('ADMIN','REVIEWER')?button('supplier-create','suppliers.create','primary','plus'):'')+`<div class="card">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('common.name'))}</th><th>${esc(t('suppliers.identity'))}</th><th>IBAN</th><th>${esc(t('common.status'))}</th><th>${esc(t('common.actions'))}</th></tr></thead><tbody>${items.map(s=>`<tr><td><strong>${esc(s.name)}</strong><span class="subline">${esc(t('common.version'))} ${num(s.version)}</span></td><td class="mono" dir="ltr">${esc(s.identity)}</td><td class="mono" dir="ltr">${s.iban?esc(s.iban.slice(0,4)+' •••• '+s.iban.slice(-4)):'—'}</td><td>${badge(s.status)}</td><td><div class="row wrap">${has('ADMIN','REVIEWER')?button('supplier-edit','common.edit','secondary small','',`data-id="${s.id}"`):''}${s.status==='PENDING'&&has('ADMIN','APPROVER')?button('supplier-verify','suppliers.verify','primary small','',`data-id="${s.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('suppliers.subtitle')}</div>`;}
function jobsPage(d){return heading('jobs.title','jobs.subtitle',button('refresh','common.refresh','secondary','refresh'))+`${!d.accountingConfigured?`<div class="notice warn">${esc(t('jobs.unconfigured'))}</div>`:''}<div class="card">${d.items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('invoices.number'))}</th><th>${esc(t('common.status'))}</th><th>${esc(t('jobs.attempts'))}</th><th>${esc(t('jobs.receipt'))}</th><th>${esc(t('jobs.error'))}</th><th>${esc(t('common.actions'))}</th></tr></thead><tbody>${d.items.map(j=>`<tr><td><a class="title-link mono" href="#invoice/${j.invoiceId}">${esc(j.invoiceId.slice(0,8))}</a>${j.sandbox?`<span class="subline">${esc(t('jobs.sandbox'))}</span>`:''}</td><td>${badge(j.status)}</td><td>${num(j.attempts)}</td><td class="mono">${esc(j.receipt||'—')}</td><td>${j.lastError?esc(errorText(j.lastError)):'—'}</td><td>${has('ADMIN','FINANCE')&&['UNKNOWN','FAILED','BLOCKED'].includes(j.status)?button('reconcile','jobs.reconcile','secondary small','',`data-id="${j.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('jobs.subtitle')}</div>`;}
function auditPage(d){return heading('audit.title','audit.subtitle',button('refresh','common.refresh','secondary','refresh'))+`<div class="notice ${d.integrityValid?'success':'error'}">${icon('shield')}${esc(t(d.integrityValid?'audit.valid':'audit.invalid'))} · ${num(d.total)}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>${esc(t('common.date'))}</th><th>${esc(t('audit.action'))}</th><th>${esc(t('audit.actor'))}</th><th>${esc(t('audit.entity'))}</th></tr></thead><tbody>${d.items.map(e=>`<tr><td>${num(e.sequence)}</td><td>${esc(date(e.at))}<span class="subline mono">${esc(e.at.slice(11,19))} UTC</span></td><td><strong>${esc(dict['audit.'+e.action]||e.action)}</strong>${e.detail?.reason?`<span class="subline">${esc(e.detail.reason)}</span>`:''}</td><td class="mono">${esc(e.actor)}</td><td class="mono">${esc(e.entity)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function usersPage(users,keys){return heading('users.title','users.subtitle',button('user-create','users.create','primary','plus'))+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('common.name'))}</th><th>${esc(t('login.username'))}</th><th>${esc(t('users.roles'))}</th><th>${esc(t('common.status'))}</th><th>${esc(t('common.actions'))}</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.login)}</td><td><div class="roles">${u.roles.map(r=>`<span class="pill gray">${esc(t('role.'+r))}</span>`).join('')}</div></td><td><span class="pill ${u.active?'green':'gray'}">${esc(t(u.active?'users.active':'users.disabled'))}</span></td><td>${button('user-edit','common.edit','secondary small','',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table></div></div><div class="card section-gap"><div class="card-header"><div><h2>${esc(t('keys.title'))}</h2><p>${esc(t('keys.scope'))}</p></div>${button('key-create','keys.create','secondary','key')}</div>${keys.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('common.name'))}</th><th>${esc(t('keys.expires'))}</th><th>${esc(t('common.status'))}</th><th>${esc(t('common.actions'))}</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${esc(k.name)}</td><td>${esc(date(k.expiresAt))}</td><td><span class="pill ${k.active?'green':'gray'}">${esc(t(k.active?'users.active':'users.disabled'))}</span></td><td>${k.active?button('key-revoke','keys.revoke','danger small','',`data-id="${k.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;}
function policyPage(p){return heading('policy.title','policy.subtitle')+`<div class="settings-grid"><form id="policy-form" class="card pad">${field('policy.name','name',p.name)}<div class="field-grid">${field('policy.currency','currency',p.currency)}${field('policy.threshold','secondApprovalThreshold',p.secondApprovalThreshold)}</div><div class="section-gap">${field('policy.taxId','buyerTaxId',p.buyerTaxId||'','text',false)}${field('policy.retention','retentionYears',p.retentionYears,'number')}</div><label class="checkbox"><input type="checkbox" name="requirePurchaseOrder" ${p.requirePurchaseOrder?'checked':''}>${esc(t('policy.requirePo'))}</label><p class="form-error" role="alert"></p>${has('ADMIN')?`<button class="btn primary section-gap" type="submit">${esc(t('common.save'))}</button>`:''}</form><div class="card pad"><h2>${esc(t('policy.mode'))}</h2><div class="section-gap">${badge(p.mode)}</div><div class="metric"><span>${esc(t('detail.policyVersion'))}</span><strong>${num(p.policyVersion)}</strong></div><p class="control-note">${esc(t('policy.note'))}</p></div></div>`;}
function systemPage(s){return heading('system.title','system.subtitle',button('refresh','common.refresh','secondary','refresh'))+`<div class="stats">${[['common.version',s.version],['system.storage','AES-256-GCM'],['system.requests',num(s.requests)],['system.errors',num(s.errors)]].map(([k,v])=>`<div class="card stat"><div class="stat-top">${esc(t(k))}</div><div class="value">${esc(v)}</div></div>`).join('')}</div><div class="settings-grid"><div class="stack"><div class="card pad"><div class="row between"><h2>${esc(t('system.validator'))}</h2><span class="pill ${s.validator.configured?'green':'amber'}">${esc(t(s.validator.configured?'system.configured':'system.missing'))}</span></div><div class="metric"><span>KoSIT</span><span>${esc(s.validator.version)}</span></div><div class="metric"><span>XRechnung</span><span>${esc(s.validator.configuration)}</span></div><p class="control-note">${esc(t('system.kositHelp'))}</p><pre class="code">python scripts/setup_kosit.py</pre></div><div class="card pad"><h2>${esc(t('nav.jobs'))}</h2><p class="section-gap">${esc(t(s.accountingConfigured?'system.configured':'jobs.unconfigured'))}</p><pre class="code">RF_ACCOUNTING_URL=https://accounting.example/api/invoices
RF_ACCOUNTING_TOKEN=...  # deployment secret
RF_ACCOUNTING_IDEMPOTENT=true</pre></div></div><div class="card pad"><h2>${esc(t('system.boundary'))}</h2><p class="section-gap muted">${esc(t('system.boundaryText'))}</p><a class="btn secondary" href="#docs/commercial-readiness">${icon('book')}${esc(t('docs.commercial-readiness'))}</a><div class="metric"><span>Java</span><span>${esc(s.java)}</span></div></div></div>`;}
const docNames=['quickstart','user-guide','architecture','api','security','validation','operations','testing','deployment','commercial-readiness','research','github'];
async function docsPage(name){if(!docNames.includes(name))name='quickstart';const response=await fetch(`/docs/${language}/${name}.md`);const text=response.ok?await response.text():t('common.empty');return heading('docs.title','docs.subtitle')+`<div class="docs-layout"><nav class="card docs-menu">${docNames.map(n=>`<button data-doc="${n}" class="${name===n?'active':''}">${esc(t('docs.'+n))}</button>`).join('')}</nav><article class="card pad"><div class="row between"><h2>${esc(t('docs.'+name))}</h2><a class="btn secondary small" href="/docs/${language}/${name}.md" download>${icon('download')}${esc(t('common.download'))}</a></div><pre class="doc-markdown section-gap">${esc(text)}</pre></article></div>`;}
function bindPage(view){
 const filtersForm=document.querySelector('#filters');filtersForm?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);filters={q:String(f.get('q')||''),stage:String(f.get('stage')||''),page:0};renderPage();});
 document.querySelector('#stage-filter')?.addEventListener('change',()=>filtersForm.requestSubmit());
 document.querySelector('#comment-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,button=f.querySelector('[type=submit]'),ctx=currentInvoice;button.disabled=true;try{await api(`/api/invoices/${ctx.id}/comment`,{method:'POST',body:{version:ctx.version,note:new FormData(f).get('note')}});toast(t('common.success'));if(route()[1]===ctx.id)await renderPage();}catch(ex){if(f.isConnected){f.querySelector('.form-error').textContent=ex.message;button.disabled=false;}}});
 document.querySelector('#policy-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f));b.policyVersion=policy.policyVersion;b.retentionYears=Number(b.retentionYears);b.requirePurchaseOrder=new FormData(f).has('requirePurchaseOrder');const submit=f.querySelector('[type=submit]');if(!submit)return;submit.disabled=true;try{policy=await api('/api/policy',{method:'PUT',body:b});toast(t('common.success'));renderShell();await renderPage();}catch(ex){if(f.isConnected){f.querySelector('.form-error').textContent=ex.message;submit.disabled=false;}}});
}
function uploadDialog(corrects=null){const pending=new Map();openDialog(corrects?'upload.correct':'upload.title',`<p class="muted">${esc(t(corrects?'upload.correctHint':'upload.description'))}</p><div class="upload-box">${icon('upload')}<label for="invoice-files">${esc(t('upload.choose'))}</label><input id="invoice-files" type="file" name="files" accept=".xml,application/xml,text/xml" ${corrects?'':'multiple'} required></div><p class="hint muted">${esc(t('upload.original'))}</p><div class="upload-progress" aria-live="polite"></div>`,async(f,d)=>{const files=f.getAll('files').filter(x=>x instanceof File&&x.size>0);if(!files.length)throw new Error(t('upload.choose'));
  for(const file of files){if(file.size>2_097_152)throw new Error(errorText('FILE_TOO_LARGE'));const signature=`${file.name}|${file.size}|${file.lastModified}`;if(!pending.has(signature))pending.set(signature,{key:crypto.randomUUID(),done:false});const item=pending.get(signature);if(item.done)continue;
   const result=await api('/api/invoices'+(corrects?'?supersedes='+encodeURIComponent(corrects):''),{method:'POST',headers:{'Content-Type':'application/xml','X-Filename':encodeURIComponent(file.name),'Idempotency-Key':item.key},body:file});item.done=true;
   if(d.isConnected){const p=document.createElement('div');p.className='result';p.textContent=file.name+' — '+t(result.duplicate?'upload.duplicate':'upload.imported');d.querySelector('.upload-progress').append(p);}
   if(corrects)location.hash='invoice/'+result.id;
  }toast(t('upload.imported'));if(!corrects){filters={q:'',stage:'',page:0};if(route()[0]!=='invoices')location.hash='invoices';else await renderPage();}return true;
 },'upload.submit');}
function invoiceAction(action){const i=currentInvoice;if(!i)return;let content,label;
 if(action==='review'){content=field('detail.costCenter','costCenter',i.metadata?.costCenter||'')+field('detail.glAccount','glAccount',i.metadata?.glAccount||'')+textarea('common.note','note');label='detail.completeReview';}
 else if(action==='approve'){content=`<div class="notice">${esc(t('detail.selfApproval'))}</div>`+textarea('common.note','note');label='detail.approve';}
 else if(action==='reject'){content=textarea('common.reason','reason');label='detail.reject';}
 else if(action==='hold'){content=`<p class="notice">${esc(t('detail.holdHelp'))}</p><label class="checkbox"><input type="checkbox" name="legalHold" ${i.legalHold?'checked':''}>${esc(t('detail.hold'))}</label><div class="section-gap">${textarea('common.reason','reason')}</div>`;label='detail.toggleHold';}
 else if(action==='revalidate'){content=`<p>${esc(t('detail.revalidateNote'))}</p>`;label='detail.revalidate';}
 else if(action==='export'){content=`<p>${esc(t('jobs.subtitle'))}</p><div class="notice ${i.policy.mode==='DEMO'?'warn':''}">${esc(t(i.policy.mode==='DEMO'?'demo.banner':'strict.banner'))}</div>`;label='detail.export';}
 openDialog(label,content,async f=>{const body={version:i.version,...Object.fromEntries(f)};if(action==='hold')body.legalHold=f.has('legalHold');await api(`/api/invoices/${i.id}/${action}`,{method:'POST',headers:action==='export'?{'Idempotency-Key':crypto.randomUUID()}:{},body});toast(t('common.success'));if(route()[1]===i.id)await renderPage();},label);
}
function supplierDialog(s=null,fromInvoice=false){let value=s||{};if(fromInvoice&&currentInvoice){const seller=currentInvoice.data.seller||{};const key=['taxId','registration','endpoint'].find(k=>seller[k]);value={name:seller.name,identity:key?`${key}:${String(seller[key]).normalize('NFKC').trim().replace(/\s+/g,' ').toUpperCase()}`:`name:${String(seller.name||'').normalize('NFKC').trim().toUpperCase()}|${seller.country||''}`,iban:currentInvoice.data.iban};}
 openDialog(s?'common.edit':'suppliers.create',field('common.name','name',value.name||'')+(s?'':field('suppliers.identity','identity',value.identity||'','text',true,'suppliers.identityHint'))+field('suppliers.iban','iban',value.iban||'','text',false)+`<p class="notice warn">${esc(t('suppliers.changeWarning'))}</p>`,async f=>{const b=Object.fromEntries(f);if(s)b.version=s.version;await api('/api/suppliers'+(s?'/'+s.id:''),{method:s?'PUT':'POST',body:b});toast(t('common.success'));await renderPage();},s?'common.save':'common.create');
}
function verifySupplier(s){openDialog('suppliers.verify',`<p><strong>${esc(s.name)}</strong></p><pre class="code">${esc(s.iban||'—')}</pre><label class="checkbox"><input type="checkbox" name="confirmedOutOfBand" required>${esc(t('suppliers.confirm'))}</label><div class="section-gap">${textarea('common.reason','reason')}</div>${s.changedBy===user.id?`<div class="notice warn">${esc(t('suppliers.creatorBlocked'))}</div>`:''}`,async f=>{await api(`/api/suppliers/${s.id}/verify`,{method:'POST',body:{version:s.version,reason:f.get('reason'),confirmedOutOfBand:f.has('confirmedOutOfBand')}});toast(t('common.success'));await renderPage();},'suppliers.verify');}
function userDialog(u=null){const roles=['ADMIN','INTAKE','REVIEWER','APPROVER','FINANCE','AUDITOR'];openDialog(u?'common.edit':'users.create',field('common.name','name',u?.name||'')+(u?'':field('login.username','login')+field('login.newPassword','password','','password'))+`<fieldset><legend>${esc(t('users.roles'))}</legend><div class="role-options">${roles.map(r=>`<label class="role-option"><input type="checkbox" name="roles" value="${r}" ${u?.roles.includes(r)?'checked':''}>${esc(t('role.'+r))}</label>`).join('')}</div></fieldset>${u?`<label class="checkbox"><input name="active" type="checkbox" ${u.active?'checked':''}>${esc(t('users.active'))}</label>`:`<p class="notice">${esc(t('users.passwordHint'))}</p>`}`,async f=>{const b=Object.fromEntries(f);b.roles=f.getAll('roles');b.active=u?f.has('active'):true;await api('/api/users'+(u?'/'+u.id:''),{method:u?'PUT':'POST',body:b});toast(t('common.success'));await renderPage();},u?'common.save':'common.create');}
function keyDialog(){openDialog('keys.create',field('common.name','name')+field('keys.days','days','30','number')+`<p class="notice">${esc(t('keys.scope'))}</p>`,async(f,d)=>{const b=Object.fromEntries(f);b.days=Number(b.days);const key=await api('/api/keys',{method:'POST',body:b});
 if(d.isConnected){d.querySelector('.dialog-body').innerHTML=`<p class="notice warn">${esc(t('keys.once'))}</p><pre class="key-secret">${esc(key.token)}</pre><p class="muted">${esc(t('keys.scope'))}</p>`;const footer=d.querySelector('.dialog-footer');footer.innerHTML=`<button type="button" class="btn primary">${esc(t('common.close'))}</button>`;footer.querySelector('button').addEventListener('click',()=>{d.close();d.remove();if(dialog===d)dialog=null;renderPage();});}return false;
 },'common.create');}
function reconcileDialog(j){const choices=j.status==='UNKNOWN'?['CONFIRM_DELIVERED','CONFIRM_NOT_DELIVERED']:['RETRY_FAILED'];const names={CONFIRM_DELIVERED:'jobs.delivered',CONFIRM_NOT_DELIVERED:'jobs.notDelivered',RETRY_FAILED:'jobs.retry'};
 openDialog('jobs.reconcile',`<p class="notice warn">${esc(t('jobs.warning'))}</p><div class="form-field"><label for="reconcile-decision">${esc(t('jobs.decision'))}</label><select id="reconcile-decision" name="decision">${choices.map(c=>`<option value="${c}">${esc(t(names[c]))}</option>`).join('')}</select></div>${field('jobs.receipt','receipt','','text',false)}${textarea('common.reason','reason')}`,async f=>{await api(`/api/jobs/${j.id}/reconcile`,{method:'POST',body:Object.fromEntries(f)});toast(t('common.success'));await renderPage();},'common.confirm');}
function changePassword(required=false){openDialog('login.changePassword',`<div class="form-field"><label for="old-password">${esc(t('login.currentPassword'))}</label><input id="old-password" name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></div>`+field('login.newPassword','newPassword','','password'),async f=>{await api('/api/auth/password',{method:'POST',body:Object.fromEntries(f)});user=null;csrf='';renderLogin();toast(t('login.passwordChanged'));},'common.save');if(required&&dialog)dialog.querySelector('.dialog-body').insertAdjacentHTML('afterbegin',`<p class="notice warn">${esc(errorText('PASSWORD_CHANGE_REQUIRED'))}</p>`);}
document.addEventListener('click',async e=>{const lang=e.target.closest('[data-lang]');if(lang){try{closeDialog();await loadLanguage(lang.dataset.lang);if(user){renderShell();renderPage();}else renderLogin();}catch(ex){toast(ex.message,true);}return;}
 const page=e.target.closest('[data-page]');if(page&&!page.disabled){filters.page=Number(page.dataset.page);renderPage();return;}
 const tab=e.target.closest('[data-tab]');if(tab){activeInvoiceTab=tab.dataset.tab;renderPage();return;}
 const doc=e.target.closest('[data-doc]');if(doc){location.hash='docs/'+doc.dataset.doc;return;}
 const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;
 try{switch(action){
  case'menu':document.querySelector('.sidebar').classList.toggle('open');break;
  case'logout':await api('/api/auth/logout',{method:'POST',body:{}});user=null;csrf='';closeDialog();renderLogin();break;
  case'password':changePassword();break;case'refresh':await renderPage();break;case'upload':uploadDialog();break;case'correction':uploadDialog(currentInvoice.id);break;
  case'review':case'approve':case'reject':case'hold':case'revalidate':case'export':invoiceAction(action);break;
  case'supplier-create':supplierDialog();break;case'supplier-from-invoice':supplierDialog(null,true);break;
  case'supplier-edit':supplierDialog(currentSuppliers.find(s=>s.id===id));break;case'supplier-verify':verifySupplier(currentSuppliers.find(s=>s.id===id));break;
  case'user-create':userDialog();break;case'user-edit':userDialog(currentUsers.find(u=>u.id===id));break;case'key-create':keyDialog();break;
  case'key-revoke':openDialog('keys.revoke',`<p>${esc(t('keys.scope'))}</p>`,async()=>{await api('/api/keys/'+id+'/revoke',{method:'POST',body:{}});await renderPage();},'common.confirm');break;
  case'reconcile':reconcileDialog(currentJobs.find(j=>j.id===id));break;
  case'review-filter':case'exception-filter':filters={q:'',stage:action==='review-filter'?'REVIEW':'EXCEPTION',page:0};location.hash='invoices';break;
  case'jobs-route':location.hash=has('ADMIN','FINANCE','AUDITOR')?'jobs':'invoices';break;
 }}catch(ex){toast(ex.message,true);}
});
window.addEventListener('hashchange',()=>{activeInvoiceTab='overview';if(user)renderPage();});
async function boot(){await loadLanguage(language);config=await api('/api/public/config');try{const me=await api('/api/auth/me');user=me.user;csrf=me.csrf;if(me.mustChangePassword){renderShell();changePassword(true);return;}policy=await api('/api/policy');renderShell();await renderPage();}catch{renderLogin();}}
boot().catch(e=>{app.innerHTML=`<main class="empty"><h1>RechnungFlow</h1><p>${esc(e.message)}</p></main>`;});
